<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_GET['round_id']??$_POST['round_id']??0);$s=$pdo->prepare('SELECT r.*,e.name event_name FROM bdc_test_scoring_rounds r JOIN bdc_test_events e ON e.id=r.event_id WHERE r.id=:r');$s->execute(['r'=>$roundId]);$round=$s->fetch();if(!$round){http_response_code(404);exit('Test round not found.');}function genHeat(PDO $p,array $r,int $j):void{$js=$p->prepare('SELECT scoring_scope FROM bdc_test_scoring_judges WHERE id=:j');$js->execute(['j'=>$j]);$scope=(string)$js->fetchColumn();$p->prepare('DELETE FROM bdc_test_scoring_marks WHERE round_id=:r AND judge_id=:j')->execute(['r'=>$r['id'],'j'=>$j]);$ins=$p->prepare('INSERT INTO bdc_test_scoring_marks(round_id,entry_id,judge_id,mark_type,alt_rank,weighted_score) VALUES(:r,:e,:j,:t,:a,:w)');foreach(['leader','follower'] as $role){if($scope!=='all'&&$scope!==$role)continue;$q=$p->prepare("SELECT id FROM bdc_test_scoring_entries WHERE round_id=:r AND dance_role=:role AND entry_status='active'");$q->execute(['r'=>$r['id'],'role'=>$role]);$ids=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));shuffle($ids);$yes=min((int)$r['yes_count'],count($ids));for($i=0;$i<$yes;$i++)$ins->execute(['r'=>$r['id'],'e'=>$ids[$i],'j'=>$j,'t'=>'yes','a'=>null,'w'=>$r['yes_weight']]);$c=$yes;foreach([1=>'alt1_weight',2=>'alt2_weight',3=>'alt3_weight'] as $a=>$w)if(isset($ids[$c]))$ins->execute(['r'=>$r['id'],'e'=>$ids[$c++],'j'=>$j,'t'=>'alt','a'=>$a,'w'=>$r[$w]]);}}function genFinal(PDO $p,array $r,int $j):void{$q=$p->prepare("SELECT id FROM bdc_test_scoring_final_pairs WHERE round_id=:r AND pairing_status='confirmed' ORDER BY pair_number");$q->execute(['r'=>$r['id']]);$ids=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));if(!$ids)throw new RuntimeException('Confirm Final pairing first.');$ranks=range(1,count($ids));shuffle($ranks);$p->prepare('DELETE FROM bdc_test_scoring_final_marks WHERE round_id=:r AND judge_id=:j')->execute(['r'=>$r['id'],'j'=>$j]);$in=$p->prepare('INSERT INTO bdc_test_scoring_final_marks(round_id,pair_id,judge_id,rank_value) VALUES(:r,:p,:j,:v)');foreach($ids as $i=>$id)$in->execute(['r'=>$r['id'],'p'=>$id,'j'=>$j,'v'=>$ranks[$i]]);}if($_SERVER['REQUEST_METHOD']==='POST'&&Csrf::verify($_POST['_csrf']??null)){$action=(string)($_POST['action']??'');$judge=(int)($_POST['judge_id']??0);if($action==='generate_judge'){if($round['round_type']==='final')genFinal($pdo,$round,$judge);else genHeat($pdo,$round,$judge);}elseif($action==='generate_all'){foreach($pdo->query('SELECT id FROM bdc_test_scoring_judges WHERE round_id='.(int)$roundId)->fetchAll(PDO::FETCH_COLUMN) as $j){if($round['round_type']==='final')genFinal($pdo,$round,(int)$j);else genHeat($pdo,$round,(int)$j);}}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test Automated Scoring</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=275" rel="stylesheet"></head><body class="bg-light"><div class="bg-danger text-white text-center fw-bold p-2">TEST ENGINE ONLY · SIMULATION & DEBUG TOOLS</div><main class="container-fluid py-4" style="max-width:1800px"><div class="d-flex justify-content-between"><div><h1 class="h3">Automated Judge Simulator</h1><p><?=e($round['event_name'])?> · <?=e($round['division'])?> · <?=e($round['round_type'])?></p></div><a class="btn btn-outline-secondary align-self-start" href="./?round_id=<?=$roundId?>">Back</a></div><form method="post" class="mb-3"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="judge_id" value="1"><button class="btn btn-primary" name="action" value="generate_all">Generate Scores for All Judges</button></form><div class="card mb-4"><div class="card-header"><strong>Judge Progress</strong></div><div class="card-body" id="judges">Loading…</div></div><div class="card"><div class="card-header d-flex justify-content-between"><div><strong>Competitor Scoring Progress</strong><div class="small text-muted">Live provisional matrix. Updates every second.</div></div><div class="d-flex gap-2"><select id="sort" class="form-select form-select-sm"><option value="score_desc">Score High → Low</option><option value="score_asc">Score Low → High</option><option value="bib">Bib</option><option value="name">Name</option><option value="original">Original</option></select><label class="btn btn-outline-secondary btn-sm"><input id="auto" type="checkbox" checked> Auto Sort</label></div></div><div class="table-responsive" style="max-height:70vh"><table class="table table-bordered mb-0"><thead id="head"></thead><tbody id="body"></tbody></table></div></div></main><script>const rid=<?=$roundId?>;let d=null,original=[];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function rows(){let a=[...d.entries];switch(document.getElementById('sort').value){case'score_asc':a.sort((x,y)=>(x.score??99999)-(y.score??99999));break;case'bib':a.sort((x,y)=>(x.bib_number??x.pair_number)-(y.bib_number??y.pair_number));break;case'name':a.sort((x,y)=>String(x.display_name??x.leader_name).localeCompare(String(y.display_name??y.leader_name)));break;case'original':a=original.map(id=>a.find(x=>(x.id??x.pair_id)===id)).filter(Boolean);break;default:if(d.round_type!=='final')a.sort((x,y)=>(y.score??0)-(x.score??0));}return a}function paint(){document.getElementById('judges').innerHTML=d.judges.map(j=>`<div class="border rounded p-2 mb-2"><strong>${esc(j.judge_name)}${Number(j.is_chief)?' ★':''}</strong> · ${esc(j.session_status)} · ${j.done}/${j.total} · ${j.percent}%</div>`).join('');document.getElementById('head').innerHTML='<tr><th>Provisional</th><th>Competitor / Couple</th>'+d.judge_columns.map(j=>`<th>J${j.judge_order}<br><small>${esc(j.judge_name)}</small></th>`).join('')+(d.round_type==='final'?'':'<th>Score</th>')+'</tr>';document.getElementById('body').innerHTML=rows().map((x,i)=>`<tr><td>${d.round_type==='final'?'—':i+1}</td><td>${d.round_type==='final'?'Couple '+x.pair_number+'<br>'+esc(x.leader_name)+' & '+esc(x.follower_name):'#'+x.bib_number+' '+esc(x.display_name)+'<br><small>'+esc(x.dance_role)+'</small>'}</td>${d.judge_columns.map(j=>`<td>${esc(x.marks[j.id]??'—')}</td>`).join('')}${d.round_type==='final'?'':`<td><strong>${Number(x.score).toFixed(1)}</strong></td>`}</tr>`).join('')}async function tick(){try{const r=await fetch('automatic-live-data.php?round_id='+rid+'&_='+Date.now(),{cache:'no-store'}),j=await r.json();if(j.ok){if(!d)original=j.entries.map(x=>x.id??x.pair_id);d=j;paint()}}catch(e){}}document.getElementById('sort').onchange=()=>d&&paint();tick();setInterval(()=>{if(!document.hidden)tick()},5000);</script></body></html>